import base64, json, os, runpy, shutil, subprocess, sys, time
from pathlib import Path
os.environ.update(HF_HUB_DISABLE_XET="1", HF_HUB_DISABLE_PROGRESS_BARS="1", HF_HOME="/tmp/e52-hf",
                  OMP_NUM_THREADS="2", VLLM_WORKER_MULTIPROC_METHOD="spawn")
started = time.time()
out = Path("/kaggle/working/e55-features-skywork")
out.mkdir(parents=True, exist_ok=True)
subprocess.run(["nvidia-smi"], check=True)
root = Path("/tmp/aimo-e52")
for name, encoded in json.loads('{"datagen/extract_familiarity.py": "", "datagen/extract_features.py": "", "datagen/merge_features.py": "", "datagen/tokenizer_check.py": "", "datagen/ingest_public.py": "", "protocols/E55_PROTOCOL.md": "", "data/probe_system_prompt.txt": "", "data/e55/instances_model.parquet": ""}').items():
    dest = root / name
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(base64.b64decode(encoded))
subprocess.run([sys.executable, "-m", "pip", "install", "--no-cache-dir", "-q", *['transformers==5.13.0', 'accelerate==1.13.0', 'huggingface-hub==1.22.0', 'tokenizers==0.22.2', 'safetensors==0.8.0', 'scikit-learn==1.8.0', 'joblib==1.5.3']], check=True)
freeze = subprocess.run([sys.executable, "-m", "pip", "freeze"], capture_output=True, text=True, check=True)
(out / "environment.txt").write_text(freeze.stdout)
steps = {
    "familiarity": ["datagen/extract_familiarity.py", "--model-id", 'Skywork/Skywork-OR1-Math-7B', "--instances", 'data/e55/instances_model.parquet',
                    "--out-dir", str(out / "familiarity-skywork")],
    "stagea": ["datagen/extract_features.py", "--model-id", 'Skywork/Skywork-OR1-Math-7B', "--instances", 'data/e55/instances_model.parquet',
               "--system-prompt-file", "data/probe_system_prompt.txt", "--out-dir", str(out / "stagea-skywork")],
    "merge": ["datagen/merge_features.py", "--features-dir", str(out / "stagea-skywork")],
}
record = {"model_id": 'Skywork/Skywork-OR1-Math-7B', "steps": {}}
for step, argv in steps.items():
    began = time.time()
    code = subprocess.run([sys.executable, *argv], cwd=root).returncode
    record["steps"][step] = {"exit_code": code, "seconds": round(time.time() - began, 1)}
    (out / "execution.json").write_text(json.dumps({**record, "end_to_end_seconds": time.time() - started}, indent=2))
for vectors in (out / "stagea-skywork").glob("shard_*/vectors"):
    shutil.rmtree(vectors)  # merged into features.npz; one file per problem would overflow the output page
raise SystemExit(max(s["exit_code"] for s in record["steps"].values()))
